    {
      name: 'agents',
      description:
        'Injects per-agent delegation tools for calling registered sub-agents.',
      configSchema: AgentsOptionsSchema,
    },
    ({ config, ai }) => {
      if (!config?.agents || config.agents.length === 0) {
