        }
        return desc;
      }

      // -- Build the output schema based on artifactStrategy ----------------

      const inlineArtifactSchema = z.object({
        name: z.string().optional().describe('Name of the artifact.'),
        content: z
          .string()
          .optional()
          .describe('Text content of the artifact.'),
      });

